79	function parseAgent(filePath) {
80	  try {
81	    const content = fs.readFileSync(filePath, 'utf-8');
82	    const { data, content: body } = matter(content);
83	    const stats = fs.statSync(filePath);
84	    return {
85	      filename: path.basename(filePath, '.md'),
86	      path: filePath,
87	      frontmatter: data,
88	      name: data.name || path.basename(filePath, '.md'),
89	      description: data.description || '',
90	      model: data.model || '',
91	      tools: data.tools || '',
92	      body: body.trim(),
93	      raw: content,
94	      updatedAt: stats.mtime.toISOString(),
95	    };
96	  } catch (e) {
97	    return null;
98	  }
99	}
