706	// Topological sort helper
707	function topoSort(nodes, edges) {
708	  const inDegree = {};
709	  const adj = {};
710	  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
711	  for (const e of edges) {
712	    adj[e.source].push(e.target);
713	    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
714	  }
715	  const queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
716	  const order = [];
717	  while (queue.length) {
718	    const id = queue.shift();
719	    order.push(id);
720	    for (const next of adj[id]) {
721	      inDegree[next]--;
722	      if (inDegree[next] === 0) queue.push(next);
723	    }
724	  }
725	  return order;
726	}
