728	function runClaudeSync(prompt) {
729	  return new Promise((resolve, reject) => {
730	    const claudePath = process.env.CLAUDE_PATH || 'claude';
731	    const childEnv = { ...process.env, HOME: os.homedir() };
732	    delete childEnv.CLAUDECODE;
733	    const proc = spawn(claudePath, ['-p'], { env: childEnv });
734	    let out = '', err = '';
735	    proc.stdout.on('data', d => { out += d.toString(); });
736	    proc.stderr.on('data', d => { err += d.toString(); });
737	    proc.on('close', code => {
738	      if (code !== 0) reject(new Error(err.trim() || `claude exited ${code}`));
739	      else resolve(out.trim());
740	    });
741	    proc.on('error', reject);
742	    proc.stdin.write(prompt, 'utf8');
743	    proc.stdin.end();
744	  });
745	}
