747	app.post('/api/orchestrations/run', async (req, res) => {
748	  res.setTimeout(0);
749	  const { nodes, edges, task } = req.body;
750	  if (!Array.isArray(nodes) || !task) return res.status(400).json({ error: 'nodes and task required' });
751	
752	  const nodeMap = Object.fromEntries(nodes.map(n => [n.id, n]));
753	  const order = topoSort(nodes, edges || []);
754	
755	  // Build agent content map from files
756	  const config = loadConfig();
757	  const projects = discoverProjects(config.projectDirs);
758	  const agentContentMap = {};
759	
760	  const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
761	  for (const a of globalAgents) agentContentMap[a.name] = a.body || a.raw;
762	
763	  for (const p of projects) {
764	    for (const a of p.agents) agentContentMap[a.name] = a.body || a.raw;
765	  }
766	
767	  const results = {};
768	  let lastOutput = task;
769	
770	  // SSE for streaming progress
771	  res.setHeader('Content-Type', 'text/event-stream');
772	  res.setHeader('Cache-Control', 'no-cache');
773	  res.setHeader('Connection', 'keep-alive');
774	
775	  const send = (data) => res.write(`data: ${JSON.stringify(data)}\n\n`);
776	
777	  try {
778	    for (const nodeId of order) {
779	      const node = nodeMap[nodeId];
780	      if (!node) continue;
781	
782	      const agentName = node.data?.agentName;
783	      const agentInstructions = agentName ? (agentContentMap[agentName] || '') : (node.data?.instructions || '');
784	      const nodeLabel = node.data?.label || agentName || nodeId;
785	
786	      send({ type: 'start', nodeId, label: nodeLabel });
787	
788	      // Build prompt for this agent
789	      const incomingEdges = (edges || []).filter(e => e.target === nodeId);
790	      let context = '';
791	      if (incomingEdges.length > 0) {
792	        context = incomingEdges.map(e => {
793	          const prevLabel = nodeMap[e.source]?.data?.label || e.source;
794	          return `## Output from ${prevLabel}:\n${results[e.source] || ''}`;
795	        }).join('\n\n');
796	      } else {
797	        context = `## Task:\n${task}`;
798	      }
799	
800	      const prompt = agentInstructions
801	        ? `${agentInstructions}\n\n---\n\n${context}\n\nProvide your response:`
802	        : `${context}\n\nProvide your response:`;
803	
804	      try {
805	        const output = await runClaudeSync(prompt);
806	        results[nodeId] = output;
807	        lastOutput = output;
808	        send({ type: 'done', nodeId, label: nodeLabel, output });
809	      } catch (err) {
810	        send({ type: 'error', nodeId, label: nodeLabel, error: err.message });
811	        break;
812	      }
813	    }
814	    send({ type: 'complete', finalOutput: lastOutput });
815	  } catch (err) {
816	    send({ type: 'error', nodeId: null, label: null, error: err.message });
817	  }
818	
819	  res.end();
820	});
